import test from 'node:test';
import assert from 'node:assert/strict';
import {toggleTodo} from '../model.js';
test('只切換指定 id 並保留其他同名項目',()=>{
  const items=[
    {id:'a',title:'相同標題',completed:false},
    {id:'b',title:'相同標題',completed:true}
  ];
  const before=structuredClone(items);
  const result=toggleTodo(items,'a');
  assert.deepEqual(result.map(x=>[x.id,x.completed]),[['a',true],['b',true]]);
  assert.deepEqual(items,before);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {toggleTodo} from '../model.js';
test('未知 id 與空陣列保持資料不變',()=>{
  const items=[{id:'a',title:'A',completed:false}];
  assert.deepEqual(toggleTodo(items,'missing'),items);
  assert.deepEqual(toggleTodo([],'missing'),[]);
});
